<?php
require_once __DIR__ . '/../config/config.php';require_once __DIR__ . '/../includes/functions.php';require_login();if(is_admin())redirect('admin/dashboard.php');
$id=(int)($_GET['course_id']??$_POST['course_id']??0);$st=$pdo->prepare("SELECT * FROM courses WHERE id=? AND status='published' AND is_free=0");$st->execute([$id]);$course=$st->fetch();if(!$course){http_response_code(404);exit('Paid course not found.');}$q=$pdo->prepare('SELECT * FROM enrollments WHERE user_id=? AND course_id=?');$q->execute([current_user()['id'],$id]);$existing=$q->fetch();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($existing && $existing['status']==='approved'){flash('success','You are already enrolled in this course.');redirect('student/dashboard.php');}try{$path=upload_file($_FILES['receipt']??[],'receipt');if($existing){if($existing['receipt_path']){$old=dirname(__DIR__).'/'.$existing['receipt_path'];if(is_file($old))unlink($old);}$up=$pdo->prepare("UPDATE enrollments SET receipt_path=?,status='pending',submitted_at=NOW(),reviewed_at=NULL WHERE id=? AND user_id=?");$up->execute([$path,$existing['id'],current_user()['id']]);}else{$ins=$pdo->prepare("INSERT INTO enrollments(user_id,course_id,status,receipt_path) VALUES(?,?,'pending',?)");$ins->execute([current_user()['id'],$id,$path]);}flash('success','Receipt submitted. Access will be granted after administrator approval.');redirect('student/dashboard.php');}catch(Throwable $e){error_log($e->getMessage());$error=$e->getMessage();}}
page_header('Submit payment receipt');?><div class="panel"><h1>Payment receipt</h1><h3><?=e($course['title'])?></h3><p>Course price: <strong><?=number_format((float)$course['price'],2)?> DZD</strong></p><p>Upload a clear payment receipt (JPG, PNG, WEBP, or PDF; maximum 8 MB).</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="course_id" value="<?=$id?>"><label>Payment receipt</label><input type="file" name="receipt" accept="image/jpeg,image/png,image/webp,application/pdf" required><button>Submit receipt</button></form></div><?php page_footer();?>
